     /* ==================== */
/* 2026 - HEADER FOOTER */
/* ==================== */

* {box-sizing: border-box; /* important - leave this */}

:root {
    --menu-logo-maxheight:50px;
    --footer-background-color:#275239;
}

html, body {
    height:100%;
    margin:0;    
}
body {
    display: flex; /* necessary for sticky footer */
    flex-direction: column; /* necessary for sticky footer */
    min-height: 100%; /* necessary for sticky footer */
    font-size: 16px;
    color:#121212;
    overflow-x:hidden;
    font-family:'Barlow', sans-serif;
    font-weight:400;
    background:#fff;
    width:100%;
    max-width:100%;
}
body.home-page {background:#fff;}
main {
    flex:1 0 auto;
    max-width:100%;
} /* necessary for sticky footer */

@media (max-width: 1000px) {
    main {margin-top:0px;}
}

/* IFrames */
iframe {max-width:90vw;margin:0;} /* Keeps youtube iframe from overflowing the site containers */ 

/* Back to top */
a.back-to-top {
    color: #fff;
    text-align: center;
    margin: 0 auto;
    position: relative;
    display: block;
    font-size: 1.2rem;
    text-decoration: none;
}

body .active, body .evodir_collapsible:hover {background-color:transparent;} /* remove bootstrap gray on level one items */

a.btn {
    display:block;
    background:#eee;
    clear: both;
    padding:4px;
    border-radius:4px;
    color:#121212;
} /* standard Button */

/* Editor fixes */
body .fa-twitter::before {content: "\e61b" !important;} /* new twitterX logo */
body div#evo_interior_breadcrumbs div.wrapper.wrapper-breadcrumbs img {display:none !important;} /* remove images globally from breadcrumb menus */
body .seven-cols .col-md-1, .seven-cols .col-sm-1, .seven-cols .col-lg-1 {width:100% !important;} /* Fix evo common calendar box widths */
body div#evo_interior_content ul {list-style-position: outside;} /* make secondary list elements line up with bullets */
/* Froala Overrides */
body .fr-view {word-wrap: break-word;}
.fr-view ul, body .fr-view ol {list-style-position: outside;} /* Correct how Froala Editor indents lists */
body .fr-view ul {list-style-type:disc !important;} /* shows the dots on unordered lists in froala */

/* WRAPPERS */
body #evo_overall_content_wrapper {
    min-height: 100%;
    display: block;
    width:100%;
    max-width: 100%;
  /* 
  background-image: url(https://themes.evogov.com/media/Slideshow/leadville1.jpg);
  background-repeat: no-repeat;
  background-size: contain;
  */
  height: 100%;
}/* Overall Wrapper */
body #evo_overall_content_wrapper.evo_menu_mobile_visible_content_wrapper {
    height:100%;
    width:100%;
    margin:0;
    padding:0;
    max-height:95vh;
    max-width:100%;
} /* evo common has y scrolling on the mobile menu/page - this fixes that */
.acsb-saturation-contrast #evo_header_wrapper {position: relative;}  /* Fixes sticky header moving when accessiBe with Vision Impaired Profile is selected*/

/* ALERTS */
#alert_wrapper {
    display:block;
    width:100%;
    background-color:#095a7d;
    height:min-content;
}
body .evo_param_grid_alert_scroll {
    z-index:5000;
    background-color: #095a7d !important;
    padding-top:0;
    padding-bottom:0;
    width: 100%;
    box-sizing: border-box;
    padding-left: 0;
    padding-right: 0;
    padding-top: 5px;
    padding-bottom: 5px;
    color: white;
