    height: 30px;
    overflow-x: hidden;
    display: none;
}

body .evo_alert_message_wrapper {white-space: nowrap;}

/* Accordions - we might move this to the applications style sheet */
body .evo_accordion {
    background-color: #eee;
    color: #444;
    cursor: pointer;
    padding: 18px;
    width: 100%;
    text-align: left;
    border: none;
    outline: none;
    transition: 1s;
}
body .evo_accordion:hover {background-color: #ccc;}
body .evo_accordion::after {
    content: '\02795';
    font-size: 13px;
    color: #777;
    float: right;
    margin-left: 5px;
}
body .evo_accordion.open::after {content:"\2796";}
body .evo_accordion_panel {
    padding: 0px 18px;
    background-color: white;
    overflow: hidden;
    transition: height 0.5s ease;
    height: 0px;
}
body .evo_accordion_panel.open {max-height: unset;}
