/* HEADER - BEGIN */
:root {
    --logo-text-main-color: #fff;
    --logo-text-main-fontsize: 1.2rem;
    --logo-text-main-fontfamily: 'Barlow', sans-serif;
    --social-media-icon-size:1rem;
    --social-media-icon-color:#fff;
}
body #header_wrapper {
    position: relative;
    z-index: 500 !important;
    width: 100%;
    max-width:100%;
    top: 0;
    background:#51706b;
    background-image:url("https://www.cassia.gov/media/design/v2header/v2header-bg.png");
    /* https://www.cassia.gov/media/design/header/header2.jpg */
