 /* Tabbed Menu Interface widget styles. Paste into the tenant
   theme CSS (or the page) once -- it drives every Tabbed Menu
   widget on the site. Per-instance colors / width ride as
   inline custom properties on .evo_tmi_wrapper. */
.evo_tmi_wrapper {
    --evo_tmi_width: 1200px;
    --evo_tmi_font: 'Barlow', sans-serif;
    --evo_tmi_body_bg: #1d4f45;
    --evo_tmi_heading_color: #ffffff;
    --evo_tmi_tab_text: #333333;
    --evo_tmi_link_color: #121212;
    --evo_tmi_active_tab_bg: #ffffff;
    --evo_tmi_active_tab_border: #472f8a;
    --evo_tmi_inactive_tab_bg: #f8f9fa;
    width: 100%;
    background: var(--evo_tmi_body_bg);
    background:url("https://www.cassia.gov/media/design/homepage/helpcenter-background-trees.jpg");
    background-repeat:no-repeat;
    background-size:cover;
    background-position:top center;
    padding:  30px 0;
    font-family: var(--evo_tmi_font);
    box-sizing: border-box;
    min-height:500px;
}
.evo_tmi_wrapper *, .evo_tmi_wrapper *::before, .evo_tmi_wrapper *::after { box-sizing: border-box; }
.evo_tmi_inner {
    width: 100%;
    max-width: var(--evo_tmi_width);
    margin: 0 auto;
    padding: 0 20px;
}
.evo_tmi_heading { margin: 0 0 18px; }
.evo_tmi_title {
    color: var(--evo_tmi_heading_color);
    font-family: var(--evo_tmi_font);
    font-size: 2rem;
    font-weight: 800;
    margin: 0;
    line-height: 1.1;
}
.evo_tmi_subtitle {
    color: var(--evo_tmi_heading_color);
    font-family: var(--evo_tmi_font);
    font-size: 1.1rem;
    font-weight: 500;
    opacity: 0.85;
    margin: 6px 0 0;
}
.evo_tmi_container {
    width: 100%;
    background: var(--evo_tmi_active_tab_bg);
    box-shadow: 0 20px 60px rgba(0,0,0,0.3);
    overflow: hidden;
}
.evo_tmi_tabs {
    display: grid;
    grid-auto-flow: column;
    grid-auto-columns: 1fr;
    background: var(--evo_tmi_inactive_tab_bg);
    border-bottom: 2px solid rgba(0,0,0,0.08);
}
.evo_tmi_tab_button {
    padding: 18px 24px;
    background: transparent;
    border: none;
    border-bottom: 3px solid transparent;
    cursor: pointer;
    font-size: 1.1rem;
    font-weight: 500;
    color: var(--evo_tmi_tab_text);
    font-family: var(--evo_tmi_font);
    text-align: center;
    transition: background 0.2s ease, color 0.2s ease;
}
.evo_tmi_tab_button:hover { background: rgba(0,0,0,0.05); }
.evo_tmi_tab_button.active {
    color: var(--evo_tmi_tab_text);
    background: var(--evo_tmi_active_tab_bg);
    font-weight: 700;
    border-bottom: 3px solid var(--evo_tmi_active_tab_border);
}
.evo_tmi_panel {
    display: none;
    padding: 40px;
    background: var(--evo_tmi_active_tab_bg);
    animation: evo_tmi_fadein 0.4s ease;
}
.evo_tmi_panel.active { display: block; }
@keyframes evo_tmi_fadein {
    from { opacity: 0; transform: translateY(8px); }
    to { opacity: 1; transform: translateY(0); }
}
/* The cta_menu renders with menu_type=grid -- a Bootstrap-free
   <div class="evo_menu_inner_wrapper"><ul class="evo_grid_menu">
   (evo_* classes only, NO nav / navbar-nav / dropdown-menu). This
   widget shows ONLY top-level items (the div requests menu depth
   1), laid out as a responsive CSS grid. The rules below also
   zero the inherited link padding, lay the list to full width,
   and hide any residual submenu markup + heading caret. */
.evo_tmi_panel .evo_menu_inner_wrapper { width: 100%; }
.evo_tmi_panel ul {
    list-style: none;
    margin: 0;
    padding: 0;
    width: 100%;
    float: none;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 10px 24px;
}
.evo_tmi_panel ul ul,
.evo_tmi_panel ul.evo_menu_dropdown,
.evo_tmi_panel ul.dropdown-menu { display: none !important; }
.evo_tmi_panel ul li { list-style: none; float: none; margin: 0; padding: 0; }
.evo_tmi_panel .evo_main_menu_heading_caret { display: none; }
.evo_tmi_panel ul li a {
    text-decoration: none;
    color: var(--evo_tmi_link_color);
    font-family: var(--evo_tmi_font);
    font-size: 1.1rem;
    font-weight: 600;
    line-height: 1.7rem;
    padding: 0;
    display: inline-flex;
    align-items: center;
    gap: 10px;
}
.evo_tmi_panel ul li a i {
    width: 26px;
    text-align: center;
    color: var(--evo_tmi_active_tab_border);
}
.evo_tmi_panel ul li a:hover {
    text-decoration: underline;
    color: var(--evo_tmi_active_tab_border);
}
@media (max-width: 768px) {
    .evo_tmi_tabs { grid-auto-flow: row; grid-auto-columns: auto; }
    .evo_tmi_tab_button {
        text-align: left;
        border-bottom: 1px solid rgba(0,0,0,0.08);
        border-left: 4px solid transparent;
    }
    .evo_tmi_tab_button.active {
        border-bottom: 1px solid rgba(0,0,0,0.08);
        border-left: 4px solid var(--evo_tmi_active_tab_border);
    }
    .evo_tmi_panel { padding: 20px; }
    .evo_tmi_panel ul { grid-template-columns: 1fr; }
} 
 /* Tabbed Calendar with Files widget styles. Paste into the
   tenant theme CSS once -- it covers every tabbed-calendar
   widget on the site. Per-instance styling overrides go as
   inline custom properties on #tabbed-calendar-wrapper. */
#tabbed-calendar-wrapper {
    --minical-font-family: 'Barlow', sans-serif;
    --minical-container-bgurl: none;
    --minical-bg: rgba(74, 62, 76, 0.8);
    --mini-calendar-gridbg: transparent;
    --minical-border-highlight: #fcfcfc;
    --minical-highlight-text: #fff;
    --minical-hover-day: #d9751e;
    --mini-calendar-buttonshighlight: #76222f;
    --minical-tab-active: #76222f;
    --minical-text-light: #fff;
    --minical-text-dark: #121212;
    --mini-calendar-monthname: #fff;
    background:
        linear-gradient(to bottom, rgba(0, 0, 0, 0.6), rgba(0, 0, 0, 0.2) 30%),
        var(--minical-container-bgurl);
    background-size: cover;
    background-repeat: no-repeat;
    background-position: center center;
    width: 100%;
    padding: 50px 0;
    display: block;
    min-height: 575px;
}
#tabbed-calendar-wrapper #evo_tcwf_wrapper {
    display: grid;
    grid-template-areas:
        "mini-calendar-tabs  mini-calendar-tabs"
        "mini-calendar-grid  mini-calendar-events";
    grid-template-columns: 1fr 1fr;
    margin: 30px auto;
    width: 100%;
    max-width: 900px;
    background: transparent;
}
#tabbed-calendar-wrapper #evo_tcwf_month_overall_wrapper {
    width: 100%;
    z-index: 2;
    border: 2px solid var(--minical-border-highlight);
    background-color: var(--minical-bg);
    border-radius: 10px;
    overflow: hidden;
    grid-area: mini-calendar-grid;
}
#tabbed-calendar-wrapper #evo_tcwf_events_wrapper {
    position: relative;
    top: 0;
    /* Negative left tucks the list against the grid wrapper
       border so there is no gap between list and grid. */
    left: -4px;
    width: 100%;
    padding: 0;
    overflow-y: auto;
    overflow-x: hidden;
    background-color: rgba(0, 0, 0, 0.3);
    border-radius: 0 10px 10px 0;
    height: 100%;
    max-height: 342px;
    grid-area: mini-calendar-events;
}
#tabbed-calendar-wrapper #evo_tcwf_events_wrapper div.evo_tcwf_event {
    display: grid;
    grid-template-rows: auto auto auto;
    grid-template-areas:
        'mini-calendar-event-name mini-calendar-event-name'
        'mini-calendar-date-text  mini-calendar-time'
        'mini-calendar-resources  mini-calendar-resources';
    margin: 1px 0;
    padding: 5px 0 5px 12px;
    background: rgba(255, 255, 255, 1);
}
#tabbed-calendar-wrapper .evo_tcwf_event a.event_title,
#tabbed-calendar-wrapper .evo_tcwf_event a.event_title:visited {
    color: #01233c;
    font-weight: 600;
    font-family: var(--minical-font-family);
    text-decoration: none;
    font-size: .9rem;
    grid-area: mini-calendar-event-name;
}
#tabbed-calendar-wrapper .evo_tcwf_event a.event_title:hover { text-decoration: underline; }
#tabbed-calendar-wrapper .evo_tcwf_event .event-date-text {
    font-family: var(--minical-font-family);
    font-size: 0.8rem;
    color: #333;
    grid-area: mini-calendar-date-text;
}
#tabbed-calendar-wrapper .evo_tcwf_event .event_start_end_time {
    display: block;
    font-size: 0.9rem;
    color: var(--minical-text-dark);
    padding: 1px 10px 3px 0;
    grid-area: mini-calendar-time;
    text-align: right;
}
#tabbed-calendar-wrapper .evo_tcwf_event .evo_tcwf_meeting_resources {
    grid-column: 1 / -1;
    grid-area: mini-calendar-resources;
    font-size: 0.85rem;
    color: var(--minical-text-dark);
    padding-top: 4px;
