#tabbed-calendar-wrapper .evo_tcwf_event .evo_tcwf_meeting_resources div.event_details_heading {
    font-weight: 500;
}
#tabbed-calendar-wrapper #evo_tcwf_wrapper #evo_tcwf_tabs {
    display: inline-block;
    z-index: 0;
    position: relative;
    top: -6px;
    /* !important beats the inline right offset the legacy
       grid-theme script sets on the element, which would
