    right: auto !important;
    margin-left: 10px;
    grid-area: mini-calendar-tabs;
    margin-bottom: 0;
}
#tabbed-calendar-wrapper #evo_tcwf_wrapper div#evo_tcwf_tabs div.evo_tcwf_tab {
