}
/* Tenant themes commonly style every table ("body table { border;
   margin; background: #fff }", "body table td { border }"). The grid
   must override each of those explicitly or the theme paints white
   cells + grey borders under the light day text. */
#tabbed-calendar-wrapper #evo_tcwf_table,
#tabbed-calendar-wrapper #evo_tcwf_table thead,
#tabbed-calendar-wrapper #evo_tcwf_table tbody,
#tabbed-calendar-wrapper #evo_tcwf_table tr,
#tabbed-calendar-wrapper #evo_tcwf_table td,
#tabbed-calendar-wrapper #evo_tcwf_table th {
