#tabbed-calendar-wrapper td.evo_tcwf_heading:nth-child(5)::after { content: "hu"; }
#tabbed-calendar-wrapper td.evo_tcwf_heading:nth-child(6)::after { content: "ri"; }
#tabbed-calendar-wrapper td.evo_tcwf_heading:nth-child(7)::after { content: "at"; }
#tabbed-calendar-wrapper .evo_tcwf_day {
