        var buttons = wrapper.querySelectorAll('.evo_tmi_tab_button');
        var panels = wrapper.querySelectorAll('.evo_tmi_panel');
        var mq = window.matchMedia('(max-width: 768px)');
        function activate(idx) {
            var i;
            for (i = 0; i < buttons.length; i++) {
                var on = (String(buttons[i].getAttribute('data-evo-tmi-target')) === String(idx));
                buttons[i].classList.toggle('active', on);
                buttons[i].setAttribute('aria-selected', on ? 'true' : 'false');
            }
            for (i = 0; i < panels.length; i++) {
                panels[i].classList.toggle('active', String(panels[i].getAttribute('data-evo-tmi-panel')) === String(idx));
            }
        }
        function collapseAll() {
            var i;
            for (i = 0; i < buttons.length; i++) { buttons[i].classList.remove('active'); buttons[i].setAttribute('aria-selected', 'false'); }
            for (i = 0; i < panels.length; i++) { panels[i].classList.remove('active'); }
        }
        var b;
        for (b = 0; b < buttons.length; b++) {
            (function (btn) {
                btn.addEventListener('click', function () {
                    var target = btn.getAttribute('data-evo-tmi-target');
                    if (mq.matches && btn.classList.contains('active')) { collapseAll(); return; }
                    activate(target);
                });
                btn.addEventListener('keydown', function (e) {
                    var prev = mq.matches ? 'ArrowUp' : 'ArrowLeft';
                    var next = mq.matches ? 'ArrowDown' : 'ArrowRight';
                    if (e.key !== prev && e.key !== next) { return; }
                    e.preventDefault();
                    var arr = Array.prototype.slice.call(buttons);
                    var cur = arr.indexOf(btn);
                    var ni = (e.key === prev) ? (cur > 0 ? cur - 1 : arr.length - 1) : (cur < arr.length - 1 ? cur + 1 : 0);
                    arr[ni].click();
                    arr[ni].focus();
                });
            })(buttons[b]);
        }
    }
    ready(function () {
        var wraps = document.querySelectorAll('.evo_tmi_wrapper');
        var i;
        for (i = 0; i < wraps.length; i++) { initOne(wraps[i]); }
    });
})();
 
 

 
 
     
         
             
                 
